public final class RepositoriesActivity extends AppScreen{protected void render(){title("Extension repositories");subtitle("Add HTTPS repository index URLs, sync metadata, remove repositories, and inspect failures.");RepositoryStore rs=new RepositoryStore(this);EditText url=new EditText(this);url.setHint("https://example.org/index.min.json");url.setSingleLine(true);body.addView(url);Button add=button("Add repository");add.setMinHeight(dp(52));add.setOnClickListener(v->{if(!rs.add(url.getText().toString()))new AlertDialog.Builder(this).setTitle("Repository not added").setMessage("Use a valid HTTPS repository URL that is not already saved.").setPositiveButton("OK",null).show();else recreate();});body.addView(add);for(String u:rs.all()){body.addView(text(u,13,true));LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);Button sync=button("Sync repository");Button remove=button("Remove repository");sync.setMinHeight(dp(52));remove.setMinHeight(dp(52));sync.setContentDescription("Sync repository");remove.setContentDescription("Remove repository");row.addView(sync,new LinearLayout.LayoutParams(0,dp(52),1));row.addView(remove,new LinearLayout.LayoutParams(0,dp(52),1));body.addView(row);sync.setOnClickListener(v->sync(u));remove.setOnClickListener(v->{rs.remove(u);recreate();});}nav();}private void sync(String u){Toast.makeText(this,"Syncing repository…",Toast.LENGTH_SHORT).show();new Thread(()->{try{List<ExtensionRecord> list=new ExtensionRepositoryClient().fetch(u);new ExtensionManager(this).save(list);runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Repository synced").setMessage(list.size()+" extension record(s) discovered. Search/playback compatibility is shown on the Extensions screen.").setPositiveButton("OK",(d,w)->recreate()).show());}catch(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Repository sync failed").setMessage(e.getMessage()).setPositiveButton("OK",null).show());}}).start();}}
